1	/**
2	 * Republish Route
3	 *
4	 * POST /republish - Batch IPNS record signing endpoint.
5	 *
6	 * Receives encrypted IPNS private keys, decrypts with epoch-derived keys,
7	 * signs IPNS records, and returns signed records. Each entry is processed
8	 * independently -- one failure does not block others.
9	 *
10	 * SECURITY:
11	 * - IPNS private keys are zeroed immediately after signing
12	 * - No key material appears in logs or error messages
13	 * - Per-entry error handling with safe error messages
14	 */
15	
16	import { Router, type Request, type Response } from 'express';
17	import { decryptWithFallback, reEncryptForEpoch } from '../services/key-manager.js';
18	import { signIpnsRecord } from '../services/ipns-signer.js';
19	import { republishEntries } from '../middleware/metrics.js';
20	import { logger } from '../services/logger.js';
21	
22	const router = Router();
23	
24	/** Shape of each entry in the republish request */
25	interface RepublishEntry {
26	  encryptedIpnsKey: string; // base64-encoded ECIES ciphertext
27	  keyEpoch: number;
28	  ipnsName: string;
29	  latestCid: string;
30	  sequenceNumber: string; // bigint as string
31	  currentEpoch: number;
32	  previousEpoch: number | null;
33	}
34	
35	/** Shape of each result in the republish response */
36	interface RepublishResult {
37	  ipnsName: string;
38	  success: boolean;
39	  signedRecord?: string; // base64-encoded marshaled IPNS record
40	  newSequenceNumber?: string;
41	  upgradedEncryptedKey?: string; // base64, present if re-encrypted for current epoch
42	  upgradedKeyEpoch?: number;
43	  error?: string;
44	}
45	
46	router.post('/republish', async (req: Request, res: Response) => {
47	  const { entries } = req.body as { entries: RepublishEntry[] };
48	
49	  if (!entries || !Array.isArray(entries)) {
50	    res.status(400).json({ error: 'Missing or invalid entries array' });
51	    return;
52	  }
53	
54	  const results: RepublishResult[] = [];
55	  let successes = 0;
56	  let failures = 0;
57	
58	  for (const entry of entries) {
59	    let ipnsPrivateKey: Uint8Array | null = null;
60	
61	    try {
62	      // 1. Decode encrypted IPNS key from base64
63	      const encryptedIpnsKey = new Uint8Array(Buffer.from(entry.encryptedIpnsKey, 'base64'));
64	
65	      // 2. Decrypt with epoch fallback
66	      const { ipnsPrivateKey: decryptedKey, usedEpoch } = await decryptWithFallback(
67	        encryptedIpnsKey,
68	        entry.currentEpoch,
69	        entry.previousEpoch
70	      );
71	      ipnsPrivateKey = decryptedKey;
72	
73	      // 3. Sign IPNS record with incremented sequence number
74	      const newSequenceNumber = BigInt(entry.sequenceNumber) + 1n;
75	      const signedRecord = await signIpnsRecord(ipnsPrivateKey, entry.latestCid, newSequenceNumber);
76	
77	      // 4. Check if re-encryption needed (used previous epoch, not current)
78	      let upgradedEncryptedKey: string | undefined;
79	      let upgradedKeyEpoch: number | undefined;
80	
81	      if (usedEpoch !== entry.currentEpoch) {
82	        const reEncrypted = await reEncryptForEpoch(ipnsPrivateKey, entry.currentEpoch);
83	        upgradedEncryptedKey = Buffer.from(reEncrypted).toString('base64');
84	        upgradedKeyEpoch = entry.currentEpoch;
85	      }
86	
87	      // 5. IMMEDIATELY zero the IPNS private key
88	      ipnsPrivateKey.fill(0);
89	      ipnsPrivateKey = null;
90	
91	      // 6. Build success result
92	      const result: RepublishResult = {
93	        ipnsName: entry.ipnsName,
94	        success: true,
95	        signedRecord: Buffer.from(signedRecord).toString('base64'),
96	        newSequenceNumber: newSequenceNumber.toString(),
97	      };
98	
99	      if (upgradedEncryptedKey) {
100	        result.upgradedEncryptedKey = upgradedEncryptedKey;
101	        result.upgradedKeyEpoch = upgradedKeyEpoch;
102	      }
103	
104	      results.push(result);
105	      successes++;
106	      republishEntries.inc({ result: 'success' });
107	    } catch (error) {
108	      // Ensure key is zeroed even on error
109	      if (ipnsPrivateKey) {
110	        ipnsPrivateKey.fill(0);
111	        ipnsPrivateKey = null;
112	      }
113	
114	      // Never include key material in error messages
115	      results.push({
116	        ipnsName: entry.ipnsName,
117	        success: false,
118	        error: error instanceof Error ? error.message : 'Unknown error',
119	      });
120	      failures++;
121	      republishEntries.inc({ result: 'failure' });
122	    }
123	  }
124	
125	  // Log processing summary (NEVER log key material)
126	  logger.info('Republish batch complete', {
127	    total: entries.length,
128	    succeeded: successes,
129	    failed: failures,
130	  });
131	
132	  res.json({ results });
133	});
134	
135	export default router;
136

