1	/**
2	 * Migration Worker Service
3	 *
4	 * Core logic for migrating encrypted pins between IPFS providers.
5	 * Runs inside TEE: decrypts provider credentials in-enclave, fetches
6	 * encrypted blobs from source, pins to destination, verifies CID integrity.
7	 *
8	 * Uses @cipherbox/sdk-core KuboProvider and PsaProvider with SSRF-safe fetch
9	 * injection for all provider operations.
10	 *
11	 * SECURITY:
12	 * - Auth tokens processed as Uint8Array and zeroed with .fill(0) in finally block
13	 * - Endpoint URLs validated against SSRF (HTTPS-only, no private IPs, DNS rebinding check)
14	 * - No plaintext content access (opaque encrypted ciphertext only)
15	 */
16	
17	import { unwrapKey } from '@cipherbox/crypto';
18	import { KuboProvider, PsaProvider } from '@cipherbox/sdk-core';
19	import { getKeypair } from './tee-keys.js';
20	import { validateEndpointUrl, validateResolvedIp, ssrfSafeFetch } from './ssrf-validation.js';
21	
22	/** Migration timeout for provider operations (generous for large files) */
23	const MIGRATION_TIMEOUT_MS = 60_000;
24	
25	export type ProviderConfig = {
26	  endpoint: string;
27	  authTokenBytes: Uint8Array; // SECURITY: Uint8Array for proper zeroing, NOT string
28	  protocol: 'psa' | 'kubo' | 'cipherbox';
29	};
30	
31	export type MigrationBatchResult = {
32	  succeeded: string[];
33	  failed: string[];
34	};
35	
36	/**
37	 * Decrypt an ECIES-encrypted provider config using TEE's current epoch key.
38	 * Returns raw bytes for parsing.
39	 */
40	async function decryptEcies(encryptedHex: string, teePrivateKey: Uint8Array): Promise<Uint8Array> {
41	  const ciphertext = new Uint8Array(Buffer.from(encryptedHex, 'hex'));
42	  return await unwrapKey(ciphertext, teePrivateKey);
43	}
44	
45	/**
46	 * Parse decrypted config bytes into ProviderConfig.
47	 * SECURITY: authToken stays as Uint8Array for proper zeroing.
48	 */
49	function parseProviderConfig(decryptedBytes: Uint8Array): ProviderConfig {
50	  const text = new TextDecoder().decode(decryptedBytes);
51	  const parsed = JSON.parse(text) as {
52	    endpoint: string;
53	    authToken?: string;
54	    protocol: 'psa' | 'kubo' | 'cipherbox';
55	  };
56	  return {
57	    endpoint: parsed.endpoint,
58	    authTokenBytes: new TextEncoder().encode(parsed.authToken ?? ''),
59	    protocol: parsed.protocol,
60	  };
61	}
62	
63	/** Get auth token as string for provider constructors -- caller must zero authTokenBytes after use */
64	function authTokenString(config: ProviderConfig): string {
65	  return new TextDecoder().decode(config.authTokenBytes);
66	}
67	
68	/**
69	 * Fetch content by CID from a gateway (fallback for PSA/CipherBox protocols
70	 * that don't support direct content retrieval).
71	 */
72	async function fetchFromGateway(cid: string): Promise<Uint8Array> {
73	  const GATEWAY_URL = process.env.IPFS_GATEWAY_URL || 'https://ipfs.io';
74	  const response = await ssrfSafeFetch(`${GATEWAY_URL}/ipfs/${encodeURIComponent(cid)}`, {
75	    signal: AbortSignal.timeout(MIGRATION_TIMEOUT_MS),
76	  });
77	  if (!response.ok) throw new Error(`Fetch from gateway failed: ${response.status}`);
78	  return new Uint8Array(await response.arrayBuffer());
79	}
80	
81	/**
82	 * Migrate a batch of CIDs from source to destination provider.
83	 * Runs inside TEE -- credentials are decrypted in-enclave only.
84	 */
85	export async function migrateBatch(
86	  cids: string[],
87	  sourceConfigEncrypted: string,
88	  destConfigEncrypted: string,
89	  currentEpoch: number
90	): Promise<MigrationBatchResult> {
91	  // 1. Get TEE private key for this epoch
92	  const keypair = await getKeypair(currentEpoch);
93	  const teePrivateKey = keypair.privateKey;
94	
95	  // 2. Decrypt provider configs in-enclave (returns Uint8Array)
96	  const sourceConfigBytes = await decryptEcies(sourceConfigEncrypted, teePrivateKey);
97	  const destConfigBytes = await decryptEcies(destConfigEncrypted, teePrivateKey);
98	
99	  // Zero TEE private key immediately after decryption
100	  teePrivateKey.fill(0);
101	
102	  const sourceConfig = parseProviderConfig(sourceConfigBytes);
103	  const destConfig = parseProviderConfig(destConfigBytes);
104	
105	  // 2b. SSRF validation on both endpoints (skipped in simulator mode)
106	  if (sourceConfig.endpoint !== 'cipherbox') {
107	    validateEndpointUrl(sourceConfig.endpoint);
108	    if (process.env.TEE_MODE !== 'simulator') {
109	      await validateResolvedIp(new URL(sourceConfig.endpoint).hostname);
110	    }
111	  }
112	  if (destConfig.endpoint !== 'cipherbox') {
113	    validateEndpointUrl(destConfig.endpoint);
114	    if (process.env.TEE_MODE !== 'simulator') {
115	      await validateResolvedIp(new URL(destConfig.endpoint).hostname);
116	    }
117	  }
118	
119	  // 3. Instantiate providers with SSRF-safe fetch injection
120	  const providerOptions = { fetchFn: ssrfSafeFetch, timeoutMs: MIGRATION_TIMEOUT_MS };
121	  const sourceToken = authTokenString(sourceConfig);
122	  const destToken = authTokenString(destConfig);
123	
124	  const sourceKubo =
125	    sourceConfig.protocol === 'kubo'
126	      ? new KuboProvider(sourceConfig.endpoint, sourceToken, providerOptions)
127	      : null;
128	  const destKubo =
129	    destConfig.protocol === 'kubo'
130	      ? new KuboProvider(destConfig.endpoint, destToken, providerOptions)
131	      : null;
132	  const destPsa =
133	    destConfig.protocol === 'psa'
134	      ? new PsaProvider(destConfig.endpoint, destToken, providerOptions)
